"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

from datetime import datetime, timedelta


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


MONTH_NAMES = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

DOW_NAMES = {
    "SUN": 0, "MON": 1, "TUE": 2, "WED": 3, "THU": 4, "FRI": 5, "SAT": 6,
}


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    if count == 0:
        return []

    fields = expr.split()
    if len(fields) != 5:
        raise CronError("Expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minute_values = parse_field(minute_field, 0, 59, None)
    hour_values = parse_field(hour_field, 0, 23, None)
    dom_values = parse_field(dom_field, 1, 31, None)
    month_values = parse_field(month_field, 1, 12, MONTH_NAMES)
    dow_values = parse_field(dow_field, 0, 7, DOW_NAMES)

    if 7 in dow_values:
        dow_values.discard(7)
        dow_values.add(0)

    dom_restricted = dom_field != "*"
    dow_restricted = dow_field != "*"

    current = start.replace(second=0, microsecond=0) + timedelta(minutes=1)
    end = start + timedelta(days=365 * 5)

    results = []
    while current <= end and len(results) < count:
        if matches(current, minute_values, hour_values, dom_values, month_values, dow_values, dom_restricted, dow_restricted):
            results.append(current)
        current += timedelta(minutes=1)

    if len(results) < count:
        raise CronError("No firing exists within five years of start")

    return results


def parse_field(field_str: str, min_val: int, max_val: int, names_dict: dict | None) -> set[int]:
    """Parse a cron field and return set of valid values."""
    if field_str == "*":
        return set(range(min_val, max_val + 1))

    values = set()
    for term in field_str.split(","):
        term = term.strip()

        if "/" in term:
            range_part, step_str = term.split("/", 1)
            try:
                step = int(step_str)
            except ValueError:
                raise CronError(f"Invalid step: {step_str}")

            if step < 1:
                raise CronError(f"Step must be >= 1, got {step}")

            if range_part == "*":
                start = min_val
                end = max_val
            elif "-" in range_part:
                range_values = parse_range(range_part, min_val, max_val, names_dict)
                start = min(range_values)
                end = max(range_values)
            else:
                start = parse_value(range_part, min_val, max_val, names_dict)
                end = max_val

            for v in range(start, end + 1, step):
                if min_val <= v <= max_val:
                    values.add(v)
        elif "-" in term:
            values.update(parse_range(term, min_val, max_val, names_dict))
        else:
            v = parse_value(term, min_val, max_val, names_dict)
            values.add(v)

    return values


def parse_value(val_str: str, min_val: int, max_val: int, names_dict: dict | None) -> int:
    """Parse a single value, handling names if provided."""
    val_str = val_str.upper()

    if names_dict and val_str in names_dict:
        return names_dict[val_str]

    try:
        v = int(val_str)
    except ValueError:
        raise CronError(f"Invalid value: {val_str}")

    if v < min_val or v > max_val:
        raise CronError(f"Value {v} out of range [{min_val}, {max_val}]")

    return v


def parse_range(range_str: str, min_val: int, max_val: int, names_dict: dict | None) -> set[int]:
    """Parse a range like A-B."""
    parts = range_str.split("-", 1)
    if len(parts) != 2:
        raise CronError(f"Invalid range: {range_str}")

    a = parse_value(parts[0], min_val, max_val, names_dict)
    b = parse_value(parts[1], min_val, max_val, names_dict)

    if a > b:
        raise CronError(f"Range low > high: {a} > {b}")

    return set(range(a, b + 1))


def matches(
    dt: datetime,
    minute_values: set[int],
    hour_values: set[int],
    dom_values: set[int],
    month_values: set[int],
    dow_values: set[int],
    dom_restricted: bool,
    dow_restricted: bool,
) -> bool:
    """Check if a datetime matches the cron expression."""
    if dt.minute not in minute_values:
        return False
    if dt.hour not in hour_values:
        return False
    if dt.month not in month_values:
        return False

    cron_dow = (dt.weekday() + 1) % 7

    if dom_restricted and dow_restricted:
        dom_match = dt.day in dom_values
        dow_match = cron_dow in dow_values
        return dom_match or dow_match
    elif dom_restricted:
        return dt.day in dom_values
    elif dow_restricted:
        return cron_dow in dow_values
    else:
        return True
